async function main() {
  const app = await import_core.NestFactory.createApplicationContext(AppModule, {
    logger: ["error", "warn"]
  });
  const createEntryCommand = app.get(CreateEntryCommand);
  const parser2 = createParser(createEntryCommand);
  try {
    await parser2.parse();
  } catch (err2) {
    console.error(`${err2.message}
 ${await parser2.getHelp()}`);
    process.exit(1);
  }
  await app.close();
}
